layers.vertex:
attribute vec3 aO; attribute float aT; uniform float uTime; varying vec3 vN, vV, vL; varying float vU;
    void main(){ float u = uTime - aT; if (u < 0. || u > 0.9){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float k = 1. - pow(1. - clamp(u/.55, 0., 1.), 3.), R = mix(.4, 6., k);
      vec3 W = aO + position*vec3(R, R*.6, R); /* flattened dome: 60% as tall */ vL = position; vN = normalize(position*vec3(1., 1.67, 1.)); vV = normalize(cameraPosition - W); vU = u;
      gl_Position = projectionMatrix*viewMatrix*vec4(W, 1.); }

layers.fragment:
uniform vec3 uC, uCl; varying vec3 vN, vV, vL; varying float vU;
    void main(){
      if (vL.y < -.02) discard;                                                   // hemisphere only
      vec3 n = normalize(vN); float nv = abs(dot(n, normalize(vV)));
      float fr = pow(1. - nv, 2.2);
      vec3 b = fract(vL*6.5 + .5); float e = min(min(b.x, b.y), b.z);             // cheap facet-ish seams
      float facet = (.35 + .65*fract(sin(dot(floor(n*9.), vec3(12.9, 78.2, 37.7)))*43758.5))*0.;
      float f = (vU < .033 ? 1.3 : 1.)*(1. - smoothstep(.45, 0.9, vU));
      float base = smoothstep(0., .06, vL.y);                                      // soft where it meets the ground
      vec3 o = (uC*(fr*.14 + facet) + uCl*pow(fr, 6.)*.09)*f*base;   // smooth, soft   // translucent: the terrain stays visible
      gl_FragColor = vec4(o, 1.);
    }

layers.vertex:
attribute vec3 aO; attribute float aT; uniform float uTime; varying vec2 vP; varying float vU;
    void main(){ float u = uTime - aT; if (u < 0. || u > 1.2){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float S = 6. + .3; vP = position.xy*S; vU = u;
      gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(position.x*S, .03, -position.y*S), 1.); }

layers.fragment:
uniform vec3 uC, uCl; varying vec2 vP; varying float vU; float lc(float d, float w){ return exp(-(d*d)/(w*w)); }
    void main(){
      float r = length(vP), a = atan(vP.y, vP.x), k = 1. - pow(1. - clamp(vU/.55, 0., 1.), 3.), R = mix(.4, 6., k);
      float ring = lc(r - R, .03) + exp(-pow((r - R)/.2, 2.))*.12;
      float c8 = pow(max(abs(cos(a*2.)), 0.), 1.)*.6 + pow(max(abs(cos(a*2. + .785)), 0.), 1.)*.4;   // 4 long + 4 short points
      float spokeL = 1.6*pow(abs(cos(a*2.)), 40.), spokeS = .9*pow(abs(cos(a*2. + 1.5708)), 40.);
      float starR = 1.7*(pow(abs(cos(a*2.)), 6.)*1. + pow(abs(sin(a*2.)), 6.)*.55);
      float star = 0.;   // no ground flower
      float f = (vU < .033 ? 1.8 : 1.)*(1. - smoothstep(.6, 1.2, vU));
      vec3 o = (uC*(ring*.8 + star*.8) + uCl*lc(r, .25)*0.)*f;
      o *= smoothstep(6. + .3, 6. + .15, r);
      if (max(o.r, max(o.g, o.b)) < .002) discard; gl_FragColor = vec4(o, 1.);
    }
